    def test_basic_case(self):
        self.assertEqual(maximum([-3, -4, 5], 3), [-4, -3, 5])

    def test_k_smaller_than_length(self):
        self.assertEqual(maximum([4, -4, 4], 2), [4, 4])

    def test_k_equals_length(self):
        self.assertEqual(maximum([1, 2, 3], 3), [1, 2, 3])

    def test_k_larger_than_length(self):
        self.assertEqual(maximum([2, 1], 5), [1, 2])

    def test_single_element(self):
        self.assertEqual(maximum([7], 1), [7])

    def test_duplicates(self):
        self.assertEqual(maximum([5, 5, 5, 5], 2), [5, 5])

    def test_negative_numbers(self):
        self.assertEqual(maximum([-1, -5, -3], 2), [-5, -3])

